# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping ProjectionConsumer service specs" do
  def projection_consumer_spec_paths
    Dir.glob(Rails.root.join("spec/services/timekeeping/projection_consumer*_spec.rb"))
  end

  def merged_projection_consumer_spec
    File.read(Rails.root.join("spec/services/timekeeping/projection_consumer_spec.rb"))
  end

  # "Merge projection_consumer_{2,3,4,5,receipts}\_spec.rb into projection_consumer_spec.rb with one example per
  # behaviour: create plus update in one batch, company mismatch, tombstone, stale rollback, foreign project and
  # replay after the flip."
  # "One copy is already weaker than the rest: the mismatch case at \_2:162 asserts only `not_to eq(200)`, so a 500
  # would pass it."
  it "keeps the ProjectionConsumer service specs in one file with no not_to eq(200) status check" do
    spec_paths = projection_consumer_spec_paths
    expect(spec_paths.map { |path| File.basename(path) }).to eq(["projection_consumer_spec.rb"])

    loose_status_checks = spec_paths.select { |path| File.read(path).match?(/not_to\s+eq\(\s*200\s*\)/) }
    expect(loose_status_checks).to be_empty
  end

  # A batch written by hand with "schema_version" => 1 keeps passing after the contract's version changes, so the
  # spec stops checking the contract. TimekeepingSnapshots.batch reads the version from the contract.
  it "builds every ProjectionConsumer spec batch through TimekeepingSnapshots.batch" do
    hand_written = projection_consumer_spec_paths.select { |path| File.read(path).include?('"schema_version" =>') }

    expect(hand_written).to be_empty
    expect(TimekeepingSnapshots.batch).to include("snapshots" => [])
  end

  # "Keep the distinct cases (miru.writer mark and non-leak, concurrency, InvalidForeignKey, value mapping, a new-id
  # conflict within a batch, an equal version ignored, a flip with P set, below P after the flip, a 409 that is not stored)."
  it "keeps the distinct ProjectionConsumer cases in the merged spec file" do
    source = merged_projection_consumer_spec

    markers = {
      "miru.writer mark" => "CREATE TRIGGER",
      "miru.writer non-leak" => "current_setting('miru.writer', true)",
      "concurrency" => "refuse_foreign_agents!",
      "committed transactions" => ":without_transaction",
      "InvalidForeignKey" => "when the user does not exist",
      "value mapping" => "non_billable",
      "equal version ignored" => "same version, other note",
      "flip with P set, below P" => "final_outbox_position: 10",
      "replay after the flip" => "idempotency_key_reused",
      "409 not stored" => "retry under the same key",
      "receipt pruning" => "expired-key",
      "mismatch pinned to 409" => "\"reason\" => \"stale_generation\""
    }

    expect(markers.reject { |_case, marker| source.include?(marker) }.keys).to be_empty
  end
end
